int main()
{
    //freopen("input.txt","r",stdin);
    string a,c;
    int b,d;
    cin >> b >> d;
    cin >> a >> c;
    long long ans=0;
    long long cnt=0;
    long long cnt1;
    int cnt2[101], pos[101],cnt3[101];
    long long l=a.length();
    long long r=c.length();
    bool fl=true;
    string w;
    w=a;
    for (int i=0;i<1000;i++)
    {
        w=w+a;
    }
    long long ll=w.length();
    long long j=0;
    long long x,y;
    bool flag=true;
    for (int i=0;i<101;i++)
    {
        pos[i]=0;
    }
