    for (i=0;(i<ll)&&(flag);i++)
    {
        if (w[i]==c[j])
        {
            j++;
            if (j==r)
            {
                j=0;
                cnt++;
                y=i;
            }
            if (j==1)
            {
                if (pos[i%l]==1)
                {
                    flag=false;
                    cnt4=cnt2[i%l];
                    cnt5=cnt3[i%l];
                    cnt=cnt-cnt2[i%l];
                    cnt1=i/l-cnt3[i%l];
                    if ((y/l)==(i/l)) fl=false;
                }
                else
                {
                    pos[i%l]=1;
                    cnt2[i%l]=cnt;
                    cnt3[i%l]=i/l;
                }
            }
        }
    }
    bool fl2=false;
    if (b>cnt5)
    {
        b-=cnt5;
        ans+=cnt4;
        ans+=(b/cnt1)*cnt;
        b=b%cnt1;
        if (b==0)
        {
            if (fl) fl2=true;
        }
    }
    else
    {
        fl=false;
    }
    w="";
    if (fl==false) w=a;
    else
    {
        for (i=(y%l)+1;i<l;i++) w.push_back(a[i]);
    }
    for (int i=0;i<b-1;i++)
    {
        w=w+a;
    }
    ll=w.length();
    j=0;
    for (i=0;i<ll;i++)
    {
        if (w[i]==c[j])
        {
            j++;
            if (j==r)
            {
                j=0;
                ans++;
            }
        }
    }
    if (fl2) ans--;
    ans/=d;
    cout << ans << endl;
    return 0;
}

